          + '<div style="height:10px;width:66%;background:var(--ks-skeleton-shimmer, var(--ks-input-bg));border-radius:var(--ks-skeleton-radius,4px);margin-bottom:8px;animation:ks-skeleton-p 1.45s ease-in-out infinite"></div>'
