      + '<span style="width:6px;height:6px;border-radius:50%;background:' + (state.lastError ? 'var(--ks-bad)' : 'var(--ks-ok)') + (state.lastError ? '' : ';animation:ks-pulse 1.2s ease-in-out infinite') + '"></span>'
